  "setupWizard.import.qrHint": { de: "QR-Dateien bleiben standardmäßig erhalten. Aufräumen kannst du später feinjustieren.", en: "QR files stay in place by default. Cleanup behavior can be fine-tuned later.", "es-MX": "Los archivos QR se conservan por defecto. La limpieza se puede ajustar después." },
  "setupWizard.intro.appearance": { de: "Willkommen bei Aero Tandem Studio. In wenigen Schritten legst du Sprache, Darstellung, Speicherort und das Import-Verhalten fest. Alles Weitere kannst du später in den Einstellungen anpassen.", en: "Welcome to Aero Tandem Studio. In just a few steps you can set language, appearance, storage, and import behavior. Everything else can be adjusted later in settings.", "es-MX": "Bienvenido a Aero Tandem Studio. En pocos pasos puedes definir idioma, apariencia, almacenamiento y comportamiento de importación. Todo lo demás se puede ajustar después en la configuración." },
  "setupWizard.intro.import": { de: "Lege hier die Import-Standards fest: Backup, Leeren, Import und Auswerfen. QR-Löschregeln und weitere Details findest du später in den Einstellungen.", en: "Set the import defaults here: backup, clear, import, and eject. QR cleanup and further details can be adjusted later in settings.", "es-MX": "Configura aquí los valores de importación: respaldo, limpiar, importar y expulsar. Las reglas de borrado QR y más detalles se pueden ajustar después." },
  "setupWizard.intro.storage": { de: "Fertige Vorgänge werden im Speicherort abgelegt. Die Standard-Dropzone kannst du gleich mit festlegen.", en: "Completed jobs are saved to the storage location. You can also set the default drop zone here.", "es-MX": "Los trabajos terminados se guardan en la ubicación de almacenamiento. Aquí también puedes definir la zona de entrega predeterminada." },
  "setupWizard.intro.upload": { de: "Upload ist optional. Wenn du ihn jetzt nicht brauchst, lass ihn einfach aus und richte den Server später ein.", en: "Upload is optional. If you do not need it right now, leave it off and set up the server later.", "es-MX": "La subida es opcional. Si no la necesitas ahora, déjala apagada y configura el servidor después." },
  "setupWizard.operatorHint": { de: "Dein Name wird als Ich-Favorit in der Crew verwendet.", en: "Your name will be used as the Me favorite in crew dropdowns.", "es-MX": "Tu nombre se usará como favorito Yo en los menús del equipo." },
